const scenes={listen:{count:'01 / 04',eyebrow:'HOLD TO TALK',html:'<span class="wave" aria-hidden="true"><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b><b></b></span><strong>I\'m listening.</strong>',footer:'Let go when you\'re done'},remember:{count:'02 / 04',eyebrow:'SAVED TO YOUR DAY',html:'<strong>Got it.</strong><p>“Ask Maya about the launch plan.”</p>',footer:'Private until you share it'},agent:{count:'03 / 04',eyebrow:'OPENAGI / WORKING',html:'<strong>On it.</strong><p>Finding the latest plan and preparing a recap.</p>',footer:'Connected over Wi-Fi'},approve:{count:'04 / 04',eyebrow:'AWAITING APPROVAL',html:'<strong>Send the recap<br>to Maya?</strong><p>Not now &nbsp; · &nbsp; Send</p>',footer:'Tap to choose'}};
const steps=[...document.querySelectorAll('.story-step')];let current='listen';
function show(key){if(key===current)return;const s=scenes[key];if(!s)return;current=key;document.getElementById('scene-count').textContent=s.count;document.getElementById('screen-eyebrow').textContent=s.eyebrow;document.getElementById('screen-content').innerHTML=s.html;document.getElementById('screen-footer').textContent=s.footer;steps.forEach(el=>el.classList.toggle('is-active',el.dataset.scene===key));}
let scheduled=false;function update(){scheduled=false;const line=innerHeight*.65;let active=steps[0];for(const step of steps){if(step.getBoundingClientRect().top<=line)active=step;}show(active.dataset.scene)}
addEventListener('scroll',()=>{if(!scheduled){scheduled=true;requestAnimationFrame(update)}},{passive:true});addEventListener('resize',update);steps.forEach(el=>el.addEventListener('click',()=>show(el.dataset.scene)));update();
